import { vi } from 'vitest';
export function mockSignal(initialValue) {
    let value = initialValue;
    return {
        get: () => value,
        peek: () => value,
        set: (newValue) => {
            value = newValue;
        },
    };
}
export function createMockSignalsService() {
    return {
        signal: mockSignal,
        // Re-evaluate the computed function on every get/peek (like real computed signals)
        computed: (fn) => ({
            get: () => fn(),
            peek: () => fn(),
            set: () => { }, // no-op for computed
        }),
        effect: vi.fn((fn) => {
            fn();
        }),
    };
}
export function createMockBookingService(config = {}) {
    const { serviceSelections = [], location = null, timezone = 'UTC', formSubmission = null, selectedPaymentOption, depositSelected, } = config;
    const serviceSelectionsSignal = mockSignal(serviceSelections);
    const locationSignal = mockSignal(location);
    const timezoneSignal = mockSignal(timezone);
    const formSubmissionSignal = mockSignal(formSubmission);
    const selectedPaymentOptionSignal = mockSignal(selectedPaymentOption);
    const depositSelectedSignal = mockSignal(depositSelected);
    return {
        serviceSelections: serviceSelectionsSignal,
        location: locationSignal,
        timezone: timezoneSignal,
        formSubmission: formSubmissionSignal,
        selectedPaymentOption: selectedPaymentOptionSignal,
        depositSelected: depositSelectedSignal,
        actions: {
            updateItem: vi.fn(),
            setItem: vi.fn(),
            addItem: vi.fn(),
            removeItem: vi.fn(),
            clearItems: vi.fn(),
            setResource: vi.fn(),
            getResourceByType: vi.fn(),
            clearResourceByType: vi.fn(),
            setLocation: vi.fn(),
            clearLocation: vi.fn(),
            setTimezone: vi.fn(),
            setFormSubmission: vi.fn(),
            clearFormSubmission: vi.fn(),
            setSelectedPaymentOption: vi.fn(),
            setDepositSelected: vi.fn(),
            setAllDay: vi.fn(),
            clearAll: vi.fn(),
            book: vi.fn(),
        },
    };
}
